function result=runV4R14GridValidationA()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();m=jsondecode(fileread(fullfile(root,'config','paperReceiverParameterManifest_stage3s_v01.json')));p=m.parameters;p.bootstrapStepBins=.05;p.highShiftThresholdBins=100;cases=[-366 0];snrs=-30:-21;rows=cell(20,11);
for ci=1:2,for si=1:10,snr=snrs(si);pe=zeros(500,1);se=zeros(500,1);for id=1:500,q=v4GenerateTrackAPacket(c,cases(ci),snr,id,980000000+ci*1000000+si*50000);paper=v4PaperNativeMidambleDecode(q,c,false);stage=v4TrackAStage55DualHypothesisDecode(q,c,p);pe(id)=sum(paper.detectedPhysicalBins~=q.truth.labels);se(id)=sum(stage.detectedPhysicalBins~=q.truth.labels);end;d=(se-pe)/23;stream=RandStream('mt19937ar','Seed',989000000+ci*100+si);draw=zeros(2000,1);for b=1:2000,idx=randi(stream,500,500,1);draw(b)=mean(d(idx));end;bounds=prctile(draw,[2.5 97.5]);paperSer=sum(pe)/11500;stageSer=sum(se)/11500;index=(ci-1)*10+si;rows(index,:)={ci,snr,500,sum(pe),sum(se),paperSer,stageSer,stageSer-paperSer,bounds(1),bounds(2),stageSer<paperSer};fprintf('R14 grid Case%d SNR%d paper=%.4f stage=%.4f\n',ci,snr,paperSer,stageSer);end,end;summary=cell2table(rows,'VariableNames',{'caseIndex','snrDb','pairedPackets','paperErrors','stageErrors','paperSer','stageSer','deltaSer','lower95','upper95','stageBetter'});result=struct('status','PASS','algorithmVersion','Stage55-A-causal-dual-hypothesis-v11','experimentConditionsFrozen',true,'summary',summary,'stageBetterAllPoints',all(summary.stageBetter));folder=fullfile(root,'results','r14','validation','track_a');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,'r14_grid_validation_a.mat'),'result','-v7.3');writetable(summary,fullfile(folder,'r14_grid_validation_a.csv'));
end
